import{_ as t,o,c as r,a5 as a}from"./chunks/framework.DJo0M80U.js";const l=JSON.parse('{"title":"分页查询","description":"","frontmatter":{"title":"分页查询","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","附录","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/附录/未分类/一发入魂/分页查询.md","filePath":"posts/java快速入门/附录/未分类/一发入魂/分页查询.md"}'),p={name:"posts/java快速入门/附录/未分类/一发入魂/分页查询.md"};function c(s,e,d,n,g,i){return o(),r("div",null,[...e[0]||(e[0]=[a("<div><p><code>BaseMapper</code>中提供了<code>2</code>个方法进行分页查询，分别是<code>selectPage</code>和<code>selectMapsPage</code>，前者会将查询的结果封装成<code>Java</code>实体对象，后者会封装成<code>Map\\&lt;String,Object\\&gt;</code>。分页查询的食用示例如下 <code>1.</code> 创建<code>mp</code>的分页拦截器，注册到<code>Spring</code>容器中</p><p>packagecom.example.mp.config; importcom.baomidou.mybatisplus.annotation.DbType; importcom.baomidou.mybatisplus.extension.plugins.MybatisPlusInterceptor; importcom.baomidou.mybatisplus.extension.plugins.inner.PaginationInnerInterceptor; importorg.springframework.context.annotation.Bean; importorg.springframework.context.annotation.Configuration;</p><p><code>@ConfigurationpublicclassMybatisPlusConfig{</code></p><p><code>/**</code> 新版</p><p>mp <strong>/@BeanpublicMybatisPlusInterceptor mybatisPlusInterceptor(){ MybatisPlusInterceptorinterceptor=newMybatisPlusInterceptor(); interceptor.addInnerInterceptor(newPaginationInnerInterceptor(DbType.MYSQL)); returninterceptor; } /</strong> 旧版<code>mp</code> 用 <code>PaginationInterceptor **/}</code> 复制代码 <code>2.</code> 执行分页查询</p><p>@TestpublicvoidtestPage(){ LambdaQueryWrapper&lt;User&gt; wrapper = newLambdaQueryWrapper&lt;&gt;(); wrapper.ge(User::getAge, 28); // 设置分页信息<code>,</code> 查第<code>3</code>页<code>,</code> 每页<code>2</code>条数据</p><p>Page&lt;User&gt; page = newPage&lt;&gt;(3, 2); // 执行分页查询</p><p>Page&lt;User&gt; userPage = userMapper.selectPage(page, wrapper); System.out.println(&quot; 总记录数</p><p>= &quot;+ userPage.getTotal()); System.out.println(&quot; 总页数</p><p>= &quot;+ userPage.getPages()); System.out.println(&quot; 当前页码</p><p>= &quot;+ userPage.getCurrent()); // 获取分页查询结果</p><p>List&lt;User&gt; records = userPage.getRecords(); records.forEach(System.out::println); } 复制代码 <code>3.</code> 结果</p><p><code>4.</code> 其他 • 注意到，分页查询总共发出了<code>2</code>次<code>SQL</code>，一次查总记录数，一次查具体数据。若希望不查总记录数，仅查分页结果。可以通过<code>Page</code>的重载构造函数，指定<code>isSearchCount</code>为<code>false</code>即可 <code>publicPage(longcurrent, longsize, booleanisSearchCount)</code>复制代码 • 在实际开发中，可能遇到多表联查的场景，此时<code>BaseMapper</code>中提供的单表分页查询的方法无法满足需求，需要自定义<code>SQL</code>，示例如下（使用单表查询的<code>SQL</code>进行演示，实际进行多表联查时，修改<code>SQL</code>语句即可） <code>1.</code> 在<code>mapper</code>接口中定义一个函数，接收一个<code>Page</code>对象为参数，并编写自定义</p><p>SQL // 这里采用纯注解方式。当然，若<code>SQL</code>比较复杂，建议还是采用<code>XML</code>的方式<code>@Select(&quot;SELECT * FROM user ${ew.customSqlSegment}&quot;)Page\\&lt;User\\&gt; selectUserPage(Page\\&lt;User\\&gt; page, @Param(Constants.WRAPPER)Wrapper\\&lt;User\\&gt; wrapper);</code> 复制代码 <code>2.</code> 执行查询</p><p>@TestpublicvoidtestPage2(){ LambdaQueryWrapper&lt;User&gt; wrapper = newLambdaQueryWrapper&lt;&gt;(); wrapper.ge(User::getAge, 28).likeRight(User::getName, &quot; 王</p><p>&quot;); Page&lt;User&gt; page = newPage&lt;&gt;(3,2); Page&lt;User&gt; userPage = userMapper.selectUserPage(page, wrapper); System.out.println(&quot; 总记录数</p><p>= &quot;+ userPage.getTotal()); System.out.println(&quot; 总页数</p><p>= &quot;+ userPage.getPages()); userPage.getRecords().forEach(System.out::println); } 复制代码 <code>3.</code> 结果</p></div>",1)])])}const m=t(p,[["render",c]]);export{l as __pageData,m as default};
